package br.com.bancohorizonte.repository; import br.com.bancohorizonte.entity.ContaBancaria; import jakarta.persistence.*; import java.util.*;
public class ContaBancariaRepository { private final EntityManager em; public ContaBancariaRepository(EntityManager em){this.em=em;} public void salvar(ContaBancaria conta){em.persist(conta);} public Optional<ContaBancaria> porIdComRelacoes(Long id){TypedQuery<ContaBancaria> q=em.createQuery("select c from ContaBancaria c join fetch c.titular join fetch c.tipoConta where c.id = :id",ContaBancaria.class);return q.setParameter("id",id).getResultStream().findFirst();} public List<ContaBancaria> porPessoa(Long pessoaId){TypedQuery<ContaBancaria> q=em.createQuery("select c from ContaBancaria c join fetch c.titular join fetch c.tipoConta where c.titular.id = :id order by c.id",ContaBancaria.class);return q.setParameter("id",pessoaId).getResultList();} public boolean existeAgenciaENumero(String agencia,String numero){TypedQuery<Long> q=em.createQuery("select count(c) from ContaBancaria c where c.agencia=:agencia and c.numero=:numero",Long.class);return q.setParameter("agencia",agencia).setParameter("numero",numero).getSingleResult()>0;} }
